class LlamaChat(ToolLoopMixin, Chat):
    "Sync chat over a local llama.cpp model: the `rishi.core.Chat` API over `ToolLoopMixin`'s tool loop."
    _runtime = 'llama'
    _dflt_cbs = [UsageCallback, ToolReminderCallback, SlidingWindowCallback]
    mk_content, mk_msg, mk_msgs = staticmethod(_mk_content), staticmethod(_mk_msg), staticmethod(_mk_msgs)

    @staticmethod
    def fmt2hist(msgs):
        "llama's messages are already canonical, so just normalize to rishi history dicts."
        return _mk_msgs(msgs)
    @staticmethod
    def hist2fmt(msgs):
        "Canonical rishi history dicts -> OpenAI-style messages for llama.cpp (past-turn media -> placeholder)."
        return [_oai_msg(_strip_media(m)) for m in listify(msgs)]

    @classmethod
    def create_engine(cls, model_id=qwen3_06b, model_path=None, quant='Q4_K_M', n_ctx=8192,
                      n_gpu_layers=0, mmproj=None, verbose=False, **kw):
        'Build a `llama_cpp.Llama`. `mmproj` adds the projector that image and audio input need. `@patch` to customize.'
        ch = None
        if mmproj:
            from llama_cpp.llama_chat_format import MTMDChatHandler
            ch = MTMDChatHandler(get_mmproj(model_id, None if mmproj is True else mmproj), verbose=verbose)
        return Llama(_get_model(model_id, model_path, quant), n_ctx=n_ctx, n_gpu_layers=n_gpu_layers,
                     chat_handler=ch, verbose=verbose, **kw)

    def __init__(self, model=None, *, runtime=None, model_path=None, engine=None,
                 quant='Q4_K_M', n_ctx=8192, n_gpu_layers=0, mmproj=None, eng_kw=None,
                 sp='', messages=None, tools=None, ctx_limit=None, approve=None, tool_max_len=None,
                 max_steps=10, parallel_tools=False, max_parallel_tools=None, final_prompt=dflt_final_prompt_, think=None,
                 temp=None, top_k=None, top_p=None, seed=None, preserve_cache=False,
                 max_output_tokens=None, comp_kw=None, cbs=None, default_cbs=True):
        model = core.split_runtime(model)[1]
        model_id = None if model is None or core._is_path(model) else model
        model_path = model_path or (model if model and core._is_path(model) else None)
        self._own_engine = engine is None
        if engine is None:
            engine = self.create_engine(model_id or qwen3_17b, model_path, quant, n_ctx=n_ctx,
                                        n_gpu_layers=n_gpu_layers, mmproj=mmproj, **(eng_kw or {}))
        self.engine = engine
        self.toolspecs = [mk_toolspec(t) for t in L(tools)]
        self.ns = mk_ns([t for t in L(tools) if callable(t)])
        self._samp = {k:v for k,v in dict(temperature=temp, top_k=top_k, top_p=top_p, seed=seed).items() if v is not None}
        store_attr('think,max_output_tokens,preserve_cache', self)
        self._cache_dirty = True     # nothing prefilled yet
        self.ctx_limit, self.comp_kw, self._ctx_tokens = ifnone(ctx_limit, engine.n_ctx()), comp_kw or {}, 0
        self._setup(model=model, sp=sp, messages=messages, tools=tools, approve=approve,
                    tool_max_len=tool_max_len, max_steps=max_steps, parallel_tools=parallel_tools,
                    max_parallel_tools=max_parallel_tools, final_prompt=final_prompt, cbs=cbs, default_cbs=default_cbs)

    def close(self):
        "Release the engine, if this Chat created it. Idempotent."
        if getattr(self, 'engine', None) is not None and getattr(self.engine, '_rishi_cache_owner', None) is self:
            self.engine._rishi_cache_owner = None
        if self._own_engine and getattr(self, 'engine', None) is not None:
            if (c := getattr(self.engine, 'close', None)): c()
            self.engine = None

    @property
    def token_count(self):
        "Tokens in the model context after the last turn (prompt + completion)."
        return self._ctx_tokens

    @property
    def cached_tokens(self):
        """Prompt tokens llama.cpp's KV cache can reuse on the next call.

        llama.cpp does this itself: `Llama.generate` compares the incoming prompt against the tokens
        already in the context and evaluates only the divergent tail, so an appended turn reuses the
        whole conversation. What it cannot tell us is *how much* it reused, so rishi tracks the one
        thing it knows, which is whether it invalidated the prefix itself."""
        owner = getattr(self.engine, '_rishi_cache_owner', None)
        return 0 if self._cache_dirty or owner is not self else getattr(self.engine, 'n_tokens', 0) or 0

    def _recreate_conv(self):
        "llama re-sends the whole message list, so there is no conversation to rebuild. A rewritten history, after eviction or context recovery, no longer matches the cached prefix."
        self._cache_dirty = True
        if getattr(self.engine, '_rishi_cache_owner', None) is self: self.engine._rishi_cache_owner = None

    def _note_cache(self, usage, cached):
        "Record the reuse this turn got, and whether the next turn can expect any."
        usage = dict(usage or {})
        usage['cached_tokens'] = min(cached, usage.get('prompt_tokens', 0))
        # media on this turn becomes an `[image]`/`[audio]` placeholder on the next one, so the
        # rendered prompt stops being an extension of what the cache holds
        cont = (self.turn_msg or {}).get('content')
        self._cache_dirty = bool(isinstance(cont, list) and any(is_media(p) for p in cont))
        self.engine._rishi_cache_owner = None if self._cache_dirty else self
        return usage

    def _isolated(self, f):
        """Run `f` on the shared engine, optionally without losing the conversation's KV cache.

        A `Llama` has one context, so any completion overwrites it. A `classify`, `structured` or `check`
        call costs the next real turn a full re-prefill. `preserve_cache=True` saves and restores the
        whole llama state around it instead. That is a large copy, so it only pays off on big contexts."""
        if not self.preserve_cache:
            self._cache_dirty = True
            if getattr(self.engine, '_rishi_cache_owner', None) is self: self.engine._rishi_cache_owner = None
            return f()
        st, owner = self.engine.save_state(), getattr(self.engine, '_rishi_cache_owner', None)
        try: return f()
        finally:
            self.engine.load_state(st)
            self.engine._rishi_cache_owner = owner

    def save_cache(self, fn):
        "Persist the llama.cpp context (KV cache plus the tokens it holds) so a later chat can skip re-prefilling it."
        st = self.engine.save_state()
        with open(fn, 'wb') as f:
            np.savez(f, input_ids=st.input_ids, scores=st.scores, n_tokens=st.n_tokens,
                     seed=st.seed if st.seed is not None else -1,
                     llama_state=np.frombuffer(st.llama_state, dtype=np.uint8))
        return self

    def load_cache(self, fn):
        "Restore a context written by `save_cache` (onto a chat built with the same model)."
        from llama_cpp.llama import LlamaState
        with np.load(str(fn)) as d:
            buf = d['llama_state'].tobytes()
            st = LlamaState(input_ids=d['input_ids'], scores=d['scores'], n_tokens=int(d['n_tokens']),
                            llama_state=buf, llama_state_size=len(buf), seed=int(d['seed']))
        self.engine.load_state(st)
        self._cache_dirty = False
        self.engine._rishi_cache_owner = self
        return self
    def count_tokens(self, text):
        "Number of tokens in `text` per the engine tokenizer."
        return len(self.engine.tokenize(text.encode('utf-8'), add_bos=False, special=True))

    @staticmethod
    def _think_sp(sp, think):
        "Qwen's own switch, written into the system prompt: `/think` or `/no_think`, or nothing said."
        sp = sp or ''
        if think is None: return sp
        return f"{sp}\n{'/think' if think else '/no_think'}".strip()

    def _sys_msgs(self):
        sp = self._think_sp(self.sp, self.think)
        return [{'role': 'system', 'content': sp}] if sp else []

    def _msgs(self):
        "OpenAI-style messages. Media in earlier turns is stripped to a placeholder so only the live turn is re-encoded, because llama.cpp re-tokenizes the whole list each call."
        return self._sys_msgs() + [_oai_msg(m if m is self.turn_msg else _strip_media(m)) for m in self.hist]

    def _step(self, max_output_tokens=None, stream=False):
        return self.engine.create_chat_completion(self._msgs(), tools=self.toolspecs or None, stream=stream,
            max_tokens=ifnone(max_output_tokens, self.max_output_tokens), **self._samp, **self.comp_kw)

    def _model_step(self, max_output_tokens=None):
        "One completion, normalized to a `Resp`. The single wire call `ToolLoopMixin` drives."
        cached = self.cached_tokens          # read before the call: it overwrites the context
        r = norm_resp(self._step(max_output_tokens))
        r['usage'] = self._note_cache(r.get('usage'), cached)
        return r

    def _oneshot(self, prompt, sp='', think=None, max_tokens=None):
        "Stateless one-shot completion text (shares the engine, so see `_isolated` about the KV cache)."
        sp = self._think_sp(sp, think)
        msgs = ([{'role':'system','content':sp}] if sp else []) + [{'role':'user','content':prompt}]
        kw = dict(self._samp)
        if max_tokens is not None: kw['max_tokens'] = int(max_tokens)
        return self._isolated(lambda: resp_text(norm_resp(self.engine.create_chat_completion(msgs, **kw))))
    def _structured_call(self, prompt, schema, sp):
        "Grammar-constrained JSON reply, returning the decoded argument dict."
        rf = {'type':'json_object','schema': get_schema(schema)['input_schema']}
        msgs = ([{'role':'system','content':sp}] if sp else []) + [{'role':'user','content':prompt}]
        return self._isolated(lambda: json.loads(resp_text(norm_resp(
            self.engine.create_chat_completion(msgs, response_format=rf, **self._samp)))))
    def _stream_step(self, max_output_tokens=None):
        "Stream one completion, yielding chunk dicts and leaving the merged `Resp` on `self._step_res`."
        cached = self.cached_tokens          # read before the call: it overwrites the context
        split, tcs, fin = StreamSplit(), [], None
        for r in self._step(max_output_tokens, stream=True):
            ch = r['choices'][0]
            fin = ch.get('finish_reason') or fin
            d = ch.get('delta') or {}
            _acc_tc(tcs, d.get('tool_calls'))
            yield from split.feed(d.get('content') or '')
        yield from split.finish()
        tcs = [{'id': tc['id'] or f'call_{i}', 'type': 'function',
                'function': {'name': tc['function']['name'], 'arguments': _parse_args(tc['function']['arguments'])}}
               for i, tc in enumerate(tcs)] + split.tool_calls
        res = {'role': 'assistant', 'content': split.text}
        if split.thought: res['channels'] = {'thought': split.thought}
        if tcs: res['tool_calls'] = tcs
        if fin == 'length': res['truncated'] = True
        out = self.count_tokens(split.text + split.thought) if (split.text or split.thought) else 0
        n = self.engine.n_tokens
        res['usage'] = self._note_cache({'prompt_tokens': max(n - out, 0), 'completion_tokens': out,
                                         'total_tokens': n}, cached)
        self._step_res = Resp(res)

